arguments.command:
cat > /tmp/git-askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
*Username*) printf '%s\n' "x-access-token" ;;
*Password*) printf '%s\n' "$GITHUB_TOKEN" ;;
*) printf '%s\n' "" ;;
esac
EOF
chmod +x /tmp/git-askpass.sh
GIT_ASKPASS=/tmp/git-askpass.sh git -C /tmp/phoebe-worktree push origin HEAD:refs/heads/friend/phoebe
